import re
import datetime

from ta_moler.events.rtg_ctrl.genericrtg_ctrl_lineevent import GenericRtgCtrlLineEvent


class CcsAssertionFailed(GenericRtgCtrlLineEvent):
    """Ccs assertion failed event class."""

    # Example line: [ 733.376394] platform[830]: ccs: CCSLiteExe: /var/fpwork/nagay/FB_CCS_SW_2016_03_032/./CCS_Lite/Realtime/Dispatcher/EMMsgPort.cpp:61: virtual void* CCS::EMMsgPort::allocMsg(size_t): Assertion `buffer!=__null' failed.
    _re_ccs_assertion_failed = re.compile(r'CCSLiteExe:.*? Assertion .*? failed\.')

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for ccs crashed.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(CcsAssertionFailed, self).__init__(connection=connection, runner=runner,
                                                 till_occurs_times=till_occurs_times,
                                                 detect_patterns=[self._re_ccs_assertion_failed],
                                                 match='any')


EVENT_OUTPUT = """[ 673.172777] platform[830]: ccs: SCH(1239): SCH-ALARM: LMTS::RMessage error - LMTS::RMessage size too big
[ 673.930866] platform[830]: ccs: CCSLiteExe 0x1239 has crashed. Core dump /ram/ccs_lite/0x1239/core.5936 stored to /var/tmp/diagn/CCSLiteExe_5936_.core.xz
[ 733.376394] platform[830]: ccs: CCSLiteExe: /var/fpwork/nagay/FB_CCS_SW_2016_03_032/./CCS_Lite/Realtime/Dispatcher/EMMsgPort.cpp:61: virtual void* CCS::EMMsgPort::allocMsg(size_t): Assertion `buffer!=__null' failed."""

EVENT_KWARGS = {"till_occurs_times": 1}

EVENT_RESULT = [{
    'line': "[ 733.376394] platform[830]: ccs: CCSLiteExe: /var/fpwork/nagay/FB_CCS_SW_2016_03_032/./CCS_Lite/Realtime/Dispatcher/EMMsgPort.cpp:61: virtual void* CCS::EMMsgPort::allocMsg(size_t): Assertion `buffer!=__null' failed.",
    'groups': (),
    'named_groups': {},
    'matched': "CCSLiteExe: /var/fpwork/nagay/FB_CCS_SW_2016_03_032/./CCS_Lite/Realtime/Dispatcher/EMMsgPort.cpp:61: virtual void* CCS::EMMsgPort::allocMsg(size_t): Assertion `buffer!=__null' failed.",
    'time': datetime.datetime.now()}]
